      "qualname": "glom/cli.py::mw_get_target",
      "source": "@face_middleware(provides=['spec', 'target'])
def mw_get_target(next_, posargs_, target_file, target_format, spec_file, spec_format):
    current_spec_text = None
    current_target_text = None

    num_args = len(posargs_)
    if num_args == 2:
        current_spec_text = posargs_[0]
        current_target_text = posargs_[1]
    elif num_args == 1:
        current_spec_text = posargs_[0]
        current_target_text = None

    if current_spec_text and spec_file:
        raise UsageError('expected spec file or spec argument, not both')
    elif spec_file:
        try:
            with open(spec_file, 'r') as f:
                current_spec_text = f.read()
        except IOError as ose:
            raise UsageError('could not read spec file %r, got: %s' % (spec_file, ose))

    resolved_spec = None
    if not current_spec_text:
        resolved_spec = Path()
    elif spec_format == 'python':
        first_char = current_spec_text[0]
        if first_char not in ('"', "'", "[", "{", "("):
            # intention: handle trivial path access, assume string
            current_spec_text = repr(current_spec_text)
        resolved_spec = ast.literal_eval(current_spec_text)
    elif spec_format == 'json':
        resolved_spec = json.loads(current_spec_text)
    elif spec_format == 'python-full':
        resolved_spec = _eval_python_full_spec(current_spec_text)
    else:
        raise UsageError('expected spec-format to be one of json, python, or python-full')

    resolved_target_text = current_target_text
    if current_target_text and target_file:
        raise UsageError('expected target file or target argument, not both')
    elif target_file == '-' or current_target_text == '-':
        resolved_target_text = sys.stdin.read()
    elif target_file:
        try:
            file_handle = open(target_file, 'r')
            resolved_target_text = file_handle.read()
            file_handle.close()
        except IOError as ose:
            raise UsageError('could not read target file %r, got: %s' % (target_file, ose))
    elif not current_target_text and not isatty(sys.stdin):
        resolved_target_text = sys.stdin.read()

    resolved_target = mw_handle_target(resolved_target_text, target_format)

    return next_(spec=resolved_spec, target=resolved_target)"
