      "qualname": "glom/core.py::format_invocation",
      "source": "def format_invocation(name='', args=(), kwargs=None, **kw):
    """Given a name, positional arguments, and keyword arguments, format
    a basic Python-style function call.

    >>> print(format_invocation('func', args=(1, 2), kwargs={'c': 3}))
    func(1, 2, c=3)
    >>> print(format_invocation('a_func', args=(1,)))
    a_func(1)
    >>> print(format_invocation('kw_func', kwargs=[('a', 1), ('b', 2)]))
    kw_func(a=1, b=2)

    """
    repr_func = kw.pop('repr', repr)
    if kw:
        unexpected_keys = ', '.join(kw.keys())
        raise TypeError('unexpected keyword args: %r' % unexpected_keys)

    effective_kwargs = kwargs or {}

    arg_strings = []
    for item in args:
        arg_strings.append(repr_func(item))
    positional_text = ', '.join(arg_strings)

    sorted_items = []
    if isinstance(effective_kwargs, dict):
        keys_list = list(effective_kwargs.keys())
        keys_list.sort()
        for key in keys_list:
            sorted_items.append((key, effective_kwargs[key]))
    else:
        sorted_items = effective_kwargs

    kwarg_strings = []
    for k, v in sorted_items:
        kwarg_strings.append('%s=%s' % (k, repr_func(v)))
    keyword_text = ', '.join(kwarg_strings)

    combined_text = positional_text
    if combined_text and keyword_text:
        combined_text += ', '
    combined_text += keyword_text

    result = '%s(%s)' % (name, combined_text)
    return result"
