      "qualname": "glom/grouping.py::GROUP",
      "source": "def GROUP(target, spec, scope):
    """
    Group mode dispatcher; also sentinel for current mode = group
    """
    recurse = lambda spec: scope[glom](target, spec, scope)
    accumulator_tree = scope[ACC_TREE]  # current acuumulator support structure

    spec_callable = getattr(spec, "agg", None)
    if callable(spec_callable):
        return spec_callable(target, accumulator_tree)
    elif callable(spec):
        return spec(target)

    spec_type = type(spec)
    if spec_type not in (dict, list):
        raise BadSpec("Group mode expected dict, list, callable, or"
                      " aggregator, not: %r" % (spec,))

    spec_identifier = id(spec)
    try:
        current_acc = accumulator_tree[spec_identifier]  # current accumulator
    except KeyError:
        current_acc = accumulator_tree[spec_identifier] = spec_type()

    if spec_type is dict:
        all_done = True
        for key_spec, val_spec in spec.items():
            if accumulator_tree.get(key_spec, None) is STOP:
                continue
            key_val = recurse(key_spec)
            if key_val is SKIP:
                all_done = False  # SKIP means we still want more vals
                continue
            if key_val is STOP:
                accumulator_tree[key_spec] = STOP
                continue
            if key_val not in current_acc:
                # TODO: guard against key == id(spec)
                accumulator_tree[key_val] = {}
            old_tree = scope[ACC_TREE]
            scope[ACC_TREE] = accumulator_tree[key_val]
            val_result = recurse(val_spec)
            if val_result is STOP:
                accumulator_tree[key_spec] = STOP
                continue
            all_done = False  # SKIP or returning a value means we still want more vals
            if val_result is not SKIP:
                current_acc[key_val] = val_result
        if all_done:
            return STOP
        return current_acc
    elif spec_type is list:
        for val_spec in spec:
            if type(val_spec) is dict:
                # doesn't make sense due to arity mismatch. did you mean [Auto({...})] ?
                raise BadSpec('dicts within lists are not'
                              ' allowed while in Group mode: %r' % spec)
            val_result = recurse(val_spec)
            if val_result is STOP:
                return STOP
            if val_result is not SKIP:
                current_acc.append(val_result)
        return current_acc
    raise ValueError("{} not a valid spec type for Group mode".format(spec_type))  # pragma: no cover"
