      "qualname": "glom/mutation.py::Delete.glomit",
      "source": "def glomit(self, target, scope):
    op_code = self.op
    arg_val = self.arg
    path_obj = self.path

    if self.path.startswith(S):
        dest_target = scope[UP]
        dest_path = self.path.from_t()
    else:
        dest_target = target
        dest_path = self.path

    dest_obj = None
    try:
        dest_obj = scope[glom](dest_target, dest_path, scope)
    except PathAccessError as pae:
        if not self.ignore_missing:
            raise
    else:
        if op_code == '[':
            try:
                del dest_obj[arg_val]
            except IndexError as e:
                if not self.ignore_missing:
                    raise PathDeleteError(e, path_obj, arg_val)
        elif op_code == '.':
            try:
                delattr(dest_obj, arg_val)
            except AttributeError as e:
                if not self.ignore_missing:
                    raise PathDeleteError(e, path_obj, arg_val)
        elif op_code == 'P':
            registry = scope[TargetRegistry]
            delete_handler = registry.get_handler('delete', dest_obj)
            try:
                delete_handler(dest_obj, arg_val)
            except Exception as e:
                if not self.ignore_missing:
                    raise PathDeleteError(e, path_obj, arg_val)

    return target"
