      "qualname": "glom/streaming.py::Iter.__repr__",
      "source": "def __repr__(self):
    base_arguments = ()
    if self.subspec != T:
        base_arguments = (self.subspec,)
    class_name = self.__class__.__name__
    base_str = format_invocation(class_name, base_arguments, repr=bbrepr)
    chunk_list = [base_str]

    reversed_stack = list(reversed(self._iter_stack))
    for fname, args_tuple, _ in reversed_stack:
        meth_func = getattr(self, fname)
        fb_builder = FunctionBuilder.from_func(meth_func)
        fb_builder.args = fb_builder.args[1:]  # drop self
        arg_names_list = fb_builder.get_arg_names()
        # TODO: something fancier with defaults:
        final_kwargs = []
        if len(args_tuple) > 1 and arg_names_list:
            args_tuple = ()
            zipped_pairs = zip(arg_names_list, args_tuple)
            final_kwargs = list(zipped_pairs)
        chunk_list.append('.' + format_invocation(fname, args_tuple, final_kwargs, repr=bbrepr))
    return ''.join(chunk_list)"
